#!/bin/bash
# checkuser-panel installer — @EduardLeetch
P=''
T=$(mktemp) || exit 1
trap 'rm -f "$T"' EXIT
printf '%s' "$P" | base64 -d | gunzip > "$T" 2>/dev/null
if [ ! -s "$T" ]; then
  echo "Error: no se pudo preparar el instalador." >&2
  exit 1
fi
chmod +x "$T"
export CHECKUSER_PANEL_DIST_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
exec "$T" "$@"
